import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherContent({ userName, teachingSubject, materials, fetchData, timetable, preSelectedGrade, setPreSelectedGrade, teacherGrades }) {
  const [formTitle, setFormTitle] = useState('');
  const [formType, setFormType] = useState('PDF'); 
  const [formFilePath, setFormFilePath] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const [formGrade, setFormGrade] = useState(teacherGrades[0] || 'Grade 10');

  useEffect(() => {
    if (preSelectedGrade) {
      setFormGrade(preSelectedGrade);
      setPreSelectedGrade(null);
    } else if (teacherGrades.length > 0 && !formGrade) {
      setFormGrade(teacherGrades[0]);
    }
  }, [preSelectedGrade, teacherGrades, formGrade, setPreSelectedGrade]);

  // යූටියුබ් ID එක කියවාගැනීමේ ලොජික් එක
  const getYoutubeId = (url) => {
    if (!url) return null;
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  // 🟢 ස්මාර්ට් ලින්ක් ලොජික් එක - ලින්ක් එකක්ද, අප්ලෝඩ් කරපු ෆයිල් එකක්ද කියා ඔටෝම හඳුනාගනී
  const getCorrectAccessUrl = (filePath) => {
    if (!filePath) return '#';
    if (filePath.startsWith('http://') || filePath.startsWith('https://')) {
      return filePath;
    }
    return `http://localhost:8082/${filePath}`;
  };

  const handlePublishLesson = (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('title', formTitle);
    formData.append('material_type', formType);
    formData.append('grade', formGrade);
    formData.append('subject', teachingSubject);
    formData.append('teacher_name', userName);

    if ((formType === 'PDF' || formType === 'Past Paper' || formType === 'Direct Video') && selectedFile) {
        formData.append('file', selectedFile); 
    } else {
        formData.append('file_path', formFilePath);
    }

    axios.post('http://localhost:8082/api/add-material', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
    }).then(res => {
      if (res.data.status === "Success") {
        alert(`✅ ${formType} Published Successfully!`);
        fetchData(); 
        setFormTitle(''); 
        setFormFilePath(''); 
        setSelectedFile(null);
      }
    }).catch(err => console.log(err));
  };

  const handleDeleteMaterial = (id) => {
    if (window.confirm("Are you sure you want to delete this resource?")) {
      axios.delete(`http://localhost:8082/api/delete-material/${id}`)
        .then(res => {
          if (res.data.status === "Success") {
            alert("🗑️ Material removed successfully!");
            fetchData();
          }
        }).catch(err => console.log(err));
    }
  };

  const myMaterials = materials.filter(m => m.subject === teachingSubject);

  return (
    <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '30px', fontFamily: 'sans-serif' }}>
      
      {/* Upload Portal Form */}
      <div>
        <h2 style={{ color: '#1e293b', margin: '0 0 15px 0', fontSize: '22px' }}>📤 Content Manager Gateway ({teachingSubject})</h2>
        <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
          <form onSubmit={handlePublishLesson} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            <input 
              type="text" 
              placeholder="Material Title (e.g., Lesson 01 - Intro to Fractions)" 
              value={formTitle} 
              onChange={e => setFormTitle(e.target.value)} 
              required 
              style={styles.fullInput} 
            />
            
            <div style={{ display: 'flex', gap: '20px' }}>
              <select value={formGrade} onChange={e => setFormGrade(e.target.value)} style={styles.fullInput}>
                {teacherGrades.length > 0 ? (
                  teacherGrades.map(g => <option key={g} value={g}>{g}</option>)
                ) : (
                  ['Grade 6', 'Grade 7', 'Grade 8', 'Grade 9', 'Grade 10', 'Grade 11', 'Grade 12'].map(g => <option key={g} value={g}>{g}</option>)
                )}
              </select>

              <select value={formType} onChange={e => { setFormType(e.target.value); setSelectedFile(null); setFormFilePath(''); }} style={styles.fullInput}>
                <option value="PDF">📚 PDF Handout Documents</option>
                <option value="Past Paper">🎯 Official Past Papers</option>
                <option value="Direct Video">📁 Direct Video Upload (MP4)</option>
                <option value="YouTube">🎬 YouTube Video Lesson</option>
                <option value="Zoom Link">🎥 Live Zoom Meeting Link</option>
                <option value="Recording">📼 Recorded Video / Drive Link</option>
              </select>
            </div>

            {formType === 'PDF' || formType === 'Past Paper' || formType === 'Direct Video' ? (
              <input 
                type="file" 
                accept={formType === 'Direct Video' ? "video/mp4,video/*" : ".pdf"} 
                onChange={e => setSelectedFile(e.target.files[0])} 
                required 
                style={styles.fileInput} 
              />
            ) : (
              <input 
                type="text" 
                placeholder={
                  formType === 'YouTube' ? "Enter YouTube Video URL..." :
                  formType === 'Zoom Link' ? "Enter Live Zoom Meeting Link..." :
                  "Enter Google Drive or Cloud Recording Link..."
                } 
                value={formFilePath} 
                onChange={e => setFormFilePath(e.target.value)} 
                required 
                style={styles.fullInput} 
              />
            )}
            
            <button type="submit" style={styles.publishBtn}>🚀 Publish Material Structure</button>
          </form>
        </div>
      </div>

      {/* RICH ARCHIVE TABLE WITH GORGEOUS DESIGN */}
      <div>
        <h3 style={{ margin: '0 0 15px 0', color: '#1e293b', fontSize: '18px' }}>📂 Published Learning Materials & Resource Matrix</h3>
        <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '800px' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #f1f5f9', color: '#64748b', fontSize: '13px', height: '45px' }}>
                <th style={{ width: '50px', paddingLeft: '10px' }}>No.</th>
                <th style={{ width: '120px' }}>Preview</th>
                <th>Material Title</th>
                <th style={{ width: '120px' }}>Grade</th>
                <th style={{ width: '150px' }}>Type</th>
                <th style={{ width: '150px' }}>Access Link</th>
                <th style={{ width: '80px', textAlign: 'center' }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {myMaterials.length > 0 ? (
                myMaterials.map((m, index) => {
                  const ytId = getYoutubeId(m.file_path);
                  
                  // 🟢 DB එකෙන් එන නම මොකක් වුණත් හඳුනාගැනීම (material_type හෝ type)
                  const actualType = m.material_type || m.type || 'Resource';

                  return (
                    <tr key={m.id || index} style={{ borderBottom: '1px solid #f8fafc', height: '80px', fontSize: '14px' }}>
                      <td style={{ fontWeight: 'bold', color: '#64748b', paddingLeft: '10px' }}>{index + 1}</td>
                      
                      {/* PREVIEW COLUMN */}
                      <td>
                        <div style={{ width: '90px', height: '55px', borderRadius: '8px', overflow: 'hidden', boxShadow: '0 2px 8px rgba(0,0,0,0.05)', backgroundColor: '#f8fafc', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                          {actualType === 'YouTube' && ytId ? (
                            <img src={`https://img.youtube.com/vi/${ytId}/mqdefault.jpg`} alt="Cover" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                          ) : actualType === 'Direct Video' ? (
                            <div style={{ width: '100%', height: '100%', backgroundColor: '#fae8ff', color: '#a21caf', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '9px', fontWeight: 'bold' }}>🎥 MP4 VIDEO</div>
                          ) : actualType === 'Zoom Link' ? (
                            <div style={{ width: '100%', height: '100%', backgroundColor: '#e0f2fe', color: '#0284c7', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '9px', fontWeight: 'bold' }}>🎥 ZOOM LIVE</div>
                          ) : actualType === 'Recording' ? (
                            <div style={{ width: '100%', height: '100%', backgroundColor: '#f3e8ff', color: '#6b21a8', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '9px', fontWeight: 'bold' }}>📼 RECORDED</div>
                          ) : actualType === 'Past Paper' ? (
                            <div style={{ width: '100%', height: '100%', backgroundColor: '#fee2e2', color: '#b91c1c', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '9px', fontWeight: 'bold' }}>📝 PAST PAPER</div>
                          ) : (
                            <div style={{ width: '100%', height: '100%', backgroundColor: '#e2e8f0', color: '#475569', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '9px', fontWeight: 'bold' }}>📄 HANDOUT</div>
                          )}
                        </div>
                      </td>

                      {/* TITLE */}
                      <td style={{ fontWeight: '600', color: '#1e293b', paddingRight: '15px' }}>{m.title}</td>
                      
                      {/* GRADE */}
                      <td>
                        <span style={{ backgroundColor: '#f1f5f9', color: '#334155', padding: '4px 10px', borderRadius: '6px', fontSize: '12px', fontWeight: 'bold' }}>
                          {m.grade}
                        </span>
                      </td>
                      
                      {/* TYPE (WITH COLORED BADGES) */}
                      <td>
                        <span style={{ 
                          padding: '5px 12px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold',
                          backgroundColor: 
                            actualType === 'PDF' ? '#dcfce7' : 
                            actualType === 'Past Paper' ? '#fee2e2' : 
                            actualType === 'YouTube' ? '#fff7ed' :
                            actualType === 'Direct Video' ? '#fae8ff' :
                            actualType === 'Zoom Link' ? '#e0f2fe' : '#f3e8ff', 
                          color: 
                            actualType === 'PDF' ? '#15803d' : 
                            actualType === 'Past Paper' ? '#b91c1c' : 
                            actualType === 'YouTube' ? '#c2410c' :
                            actualType === 'Direct Video' ? '#a21caf' :
                            actualType === 'Zoom Link' ? '#0369a1' : '#6b21a8'
                        }}>
                          {actualType}
                        </span>
                      </td>

                      {/* ACCESS LINK */}
                      <td>
                        <a 
                          href={getCorrectAccessUrl(m.file_path)} 
                          target="_blank" 
                          rel="noreferrer" 
                          style={{ 
                            color: '#15803d', 
                            fontWeight: 'bold', 
                            textDecoration: 'none', 
                            display: 'inline-flex', 
                            alignItems: 'center', 
                            gap: '5px',
                            backgroundColor: '#f0fdf4',
                            padding: '6px 12px',
                            borderRadius: '6px',
                            fontSize: '12.5px',
                            border: '1px solid #bbf7d0'
                          }}
                        >
                          Open Link ➔
                        </a>
                      </td>

                      {/* ACTION BUTTON */}
                      <td style={{ textAlign: 'center' }}>
                        <button 
                          onClick={() => handleDeleteMaterial(m.id)} 
                          style={{ 
                            backgroundColor: '#fee2e2', 
                            color: '#b91c1c', 
                            border: 'none', 
                            padding: '8px 12px', 
                            borderRadius: '6px', 
                            cursor: 'pointer', 
                            fontWeight: 'bold', 
                            fontSize: '12px',
                            transition: '0.2s'
                          }}
                          onMouseOver={e => e.currentTarget.style.backgroundColor='#fca5a5'}
                          onMouseOut={e => e.currentTarget.style.backgroundColor='#fee2e2'}
                        >
                          🗑️ Delete
                        </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan="7" style={{ textAlign: 'center', padding: '40px', color: '#94a3b8' }}>
                    📭 No resources published under this subject criteria yet.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
}

const styles = {
  fullInput: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', fontSize: '14px', transition: '0.2s' },
  fileInput: { width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', fontSize: '14px' },
  publishBtn: { padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px', width: '100%', marginTop: '5px', transition: '0.2s' }
};
